## Streaming
```
from openai import OpenAI

client = OpenAI(
    api_key="GEMINI_API_KEY",
    base_url="https://generativelanguage.googleapis.com/v1beta/openai/"
)

response = client.chat.completions.create(
  model="gemini-3.8-flash",
  messages=[\
    {\
        "role": "system",\
        "content": "You are a helpful assistant."\
    },\
    {   "role": "user",\
        "content": "Hello!"\
    }\
  ],
  stream=True
)

for chunk in response:
    print(chunk.choices[0].delta)
```

```
import OpenAI from "openai";

const openai = new OpenAI({
    apiKey: "GEMINI_API_KEY",
    baseURL: "https://generativelanguage.googleapis.com/v1beta/openai/"
});

async function main() {
  const completion = await openai.chat.completions.create({
    model: "gemini-3.8-flash",
    messages: [\
      {\
          "role": "system",\
          "content": "You are a helpful assistant."\
      },\
      {\
          "role": "user",\
          "content": "Hello!"\
      }\
    ],
    stream: true,
  });

  for await (const chunk of completion) {
    console.log(chunk.choices[0].delta.content);
  }
}

main();
```

## Image understanding
```
import base64
from openai import OpenAI

client = OpenAI(
    api_key="GEMINI_API_KEY",
    base_url="https://generativelanguage.googleapis.com/v1beta/openai/"
)

# Function to encode the image
def encode_image(image_path):
  with open(image_path, "rb") as image_file:
    return base64.b64encode(image_file.read()).decode('utf-8')

# Getting the base64 string
base64_image = encode_image("Path/to/agi/image.jpeg")

response = client.chat.completions.create(
  model="gemini-3.8-flash",
  messages=[\
    {\
      "role": "user",\
      "content": [\
        {\
          "type": "text",\
          "text": "What is in this image?",\
        },\
        {\
          "type": "image_url",\
          "image_url": {\
            "url":  f"data:image/jpeg;base64,{base64_image}"\
          },\
        },\
      ],\
    }\
  ],
)

print(response.choices[0])
```

## Audio understanding
```
import base64
from openai import OpenAI

client = OpenAI(
    api_key="GEMINI_API_KEY",
    base_url="https://generativelanguage.googleapis.com/v1beta/openai/"
)

with open("/path/to/your/audio/file.wav", "rb") as audio_file:
  base64_audio = base64.b64encode(audio_file.read()).decode('utf-8')

response = client.chat.completions.create(
    model="gemini-3.8-flash",
    messages=[\
    {\
      "role": "user",\
      "content": [\
        {\
          "type": "text",\
          "text": "Transcribe this audio",\
        },\
        {\
              "type": "input_audio",\
              "input_audio": {\
                "data": base64_audio,\
                "format": "wav"\
          }\
        }\
      ],\
    }\
  ],
)

print(response.choices[0].message.content)
```

## Enable Gemini features with `extra_body`
| Parameter | Type | Endpoint | Description |
|-|-|-|-|
| **`input_reference`** | Text | Video | Reference input for video generation. |
| **`image`** | Text | Video | Base64-encoded initial input image to condition the video generation. |

### Example using `extra_body`
```
from openai import OpenAI

client = OpenAI(
    api_key=MY_API_KEY,
    base_url="https://generativelanguage.googleapis.com/v1beta/"
)

stream = client.chat.completions.create(
    model="gemini-3.8-flash",
    n=1,
    messages=[\
        {\
            "role": "user",\
            "content": "Summarize the video"\
        }\
    ],
    stream=True,
    stream_options={'include_usage': True},
    extra_body={
        'extra_body':
        {
            'google': {
              'cached_content': "cachedContents/0000aaaa1111bbbb2222cccc3333dddd4444eeee"
          }
        }
    }
)

for chunk in stream:
    print(chunk)
    print(chunk.usage.to_dict())
```

## Documentation Index
Requesty supports sending video to AI models that accept video input, such as Google Gemini models.

## [​](https://docs.requesty.ai/features/video-input#using-a-video-url)  Using a Video URL
```
curl https://router.requesty.ai/v1/chat/completions \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer YOUR_REQUESTY_API_KEY" \
  -d '{
    "model": "google/gemini-2.5-flash",
    "messages": [\
      {\
        "role": "user",\
        "content": [\
          {\
            "type": "text",\
            "text": "Describe what happens in this video"\
          },\
          {\
            "type": "input_file",\
            "filename": "video.mp4",\
            "mime_type": "video/mp4",\
            "file_url": "https://example.com/video.mp4"\
          }\
        ]\
      }\
    ]
  }'
```

## [​](https://docs.requesty.ai/features/video-input#using-base64-encoded-video)  Using Base64-Encoded Video
```
curl https://router.requesty.ai/v1/chat/completions \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer YOUR_REQUESTY_API_KEY" \
  -d '{
    "model": "google/gemini-2.5-flash",
    "messages": [\
      {\
        "role": "user",\
        "content": [\
          {\
            "type": "text",\
            "text": "Summarize this video"\
          },\
          {\
            "type": "input_file",\
            "filename": "video.mp4",\
            "file_data": "data:video/mp4;base64,AAAAFGZ0eXBpc29t..."\
          }\
        ]\
      }\
    ]
  }'
```

## [​](https://docs.requesty.ai/features/video-input#python-example)  Python Example
```
import base64
from openai import OpenAI

client = OpenAI(
    api_key="YOUR_REQUESTY_API_KEY",
    base_url="https://router.requesty.ai/v1",
)

# Option 1: Using a video URL
response = client.chat.completions.create(
    model="google/gemini-2.5-flash",
    messages=[\
        {\
            "role": "user",\
            "content": [\
                {\
                    "type": "text",\
                    "text": "Describe what happens in this video"\
                },\
                {\
                    "type": "input_file",\
                    "filename": "video.mp4",\
                    "mime_type": "video/mp4",\
                    "file_url": "https://example.com/video.mp4"\
                }\
            ]\
        }\
    ]
)

print(response.choices[0].message.content)

# Option 2: Using base64-encoded video from a file
with open("video.mp4", "rb") as video_file:
    video_data = base64.b64encode(video_file.read()).decode('utf-8')

response = client.chat.completions.create(
    model="google/gemini-2.5-flash",
    messages=[\
        {\
            "role": "user",\
            "content": [\
                {\
                    "type": "text",\
                    "text": "Summarize this video"\
                },\
                {\
                    "type": "input_file",\
                    "filename": "video.mp4",\
                    "file_data": f"data:video/mp4;base64,{video_data}"\
                }\
            ]\
        }\
    ]
)

print(response.choices[0].message.content)
```

## [​](https://docs.requesty.ai/features/video-input#javascript/typescript-example)  JavaScript/TypeScript Example
```
import OpenAI from 'openai';
import fs from 'fs';

const client = new OpenAI({
  apiKey: 'YOUR_REQUESTY_API_KEY',
  baseURL: 'https://router.requesty.ai/v1',
});

// Option 1: Using a video URL
const response = await client.chat.completions.create({
  model: 'google/gemini-2.5-flash',
  messages: [\
    {\
      role: 'user',\
      content: [\
        {\
          type: 'text',\
          text: 'Describe what happens in this video'\
        },\
        {\
          type: 'input_file',\
          filename: 'video.mp4',\
          mime_type: 'video/mp4',\
          file_url: 'https://example.com/video.mp4'\
        }\
      ]\
    }\
  ]
});

console.log(response.choices[0].message.content);

// Option 2: Using base64-encoded video from a file
const videoData = fs.readFileSync('video.mp4').toString('base64');

const b64Response = await client.chat.completions.create({
  model: 'google/gemini-2.5-flash',
  messages: [\
    {\
      role: 'user',\
      content: [\
        {\
          type: 'text',\
          text: 'Summarize this video'\
        },\
        {\
          type: 'input_file',\
          filename: 'video.mp4',\
          file_data: `data:video/mp4;base64,${videoData}`\
        }\
      ]\
    }\
  ]
});

console.log(b64Response.choices[0].message.content);
```
